const CONTACT={phone:'',email:''};
const dialog=document.querySelector('#dialog');
function show(title,content){document.querySelector('#dialog-title').textContent=title;document.querySelector('#dialog-content').replaceChildren(content);dialog.showModal()}
function note(text){const p=document.createElement('p');p.textContent=text;return p}
document.querySelector('.close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.querySelectorAll('[data-whatsapp]').forEach(b=>b.addEventListener('click',()=>{if(CONTACT.phone)window.open('https://wa.me/'+CONTACT.phone+'?text='+encodeURIComponent('Bună ziua! Aș dori să discutăm despre o lucrare de instalații.'),'_blank','noopener');else show('Contact WhatsApp',note('Numărul de contact va fi disponibil în curând. Momentan nu se poate trimite un mesaj către Bandas Mircea.'))}));
document.querySelectorAll('[data-call]').forEach(b=>b.addEventListener('click',()=>{if(CONTACT.phone)location.href='tel:+'+CONTACT.phone;else show('Contact telefonic',note('Numărul de telefon va fi disponibil în curând.'))}));
document.querySelector('[data-service]').addEventListener('click',()=>{document.querySelector('select[name=service]').value='Instalații electrice'});
document.querySelectorAll('.privacy-link').forEach(b=>b.addEventListener('click',()=>show('Confidențialitate',note('Datele completate în formular sunt folosite pentru a pregăti solicitarea ta. Nu sunt trimise automat și nu sunt salvate de acest site. Dacă alegi trimiterea prin WhatsApp sau e-mail, datele vor fi transmise prin serviciul ales, conform politicii acestuia, pentru discutarea lucrării și contactarea ta. Site-ul nu folosește cookie-uri de analiză sau publicitate.'))));
document.querySelector('#contact-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const msg=`Bună ziua! Sunt ${f.get('name')}.\nTelefon: ${f.get('phone')}\nServiciu: ${f.get('service')}\nLocalitate: ${f.get('location')}\n\n${f.get('message')}`;const content=document.createElement('div');content.append(note('Verifică solicitarea înainte de trimitere.'));const ta=document.createElement('textarea');ta.value=msg;ta.readOnly=true;ta.setAttribute('aria-label','Solicitarea pregătită');content.append(ta);if(CONTACT.phone||CONTACT.email){const a=document.createElement('a');a.className='button';a.style.marginTop='18px';a.textContent=CONTACT.phone?'Trimite prin WhatsApp':'Trimite prin e-mail';a.href=CONTACT.phone?'https://wa.me/'+CONTACT.phone+'?text='+encodeURIComponent(msg):'mailto:'+CONTACT.email+'?subject='+encodeURIComponent('Solicitare instalații — '+f.get('service'))+'&body='+encodeURIComponent(msg);a.target='_blank';a.rel='noopener';content.append(a)}else{content.append(note('Solicitarea nu a fost trimisă. Datele de contact ale lui Bandas Mircea urmează să fie completate.'));const copy=document.createElement('button');copy.className='button';copy.textContent='Copiază solicitarea';copy.onclick=async()=>{try{await navigator.clipboard.writeText(msg);copy.textContent='Solicitare copiată'}catch{ta.select();copy.textContent='Selectat — copiază textul'}};content.append(copy)}show('Solicitarea ta',content)});
